<?php
$status=query_input('status'); $search=query_input('search'); $params=[]; $where=["role='resident'"]; $invalid=false;
if ($status!=='') { if(!in_array($status,['Pending','Approved','Rejected'],true)) $invalid=true; else { $where[]='status=?'; $params[]=$status==='Approved'?'Verified':$status; } }
if(isset($_GET['search'])) { if(!valid_text($search,255)) $invalid=true; else { $where[]="(CONCAT(first_name,' ',last_name) LIKE ? OR email LIKE ?)"; $params[]='%'.$search.'%'; $params[]='%'.$search.'%'; } }
$residents=$invalid?[]:rows('SELECT * FROM users WHERE '.implode(' AND ',$where).' ORDER BY created_at DESC,id DESC',$params);
?>
<div class="section-title"><h2>Resident registrations</h2><button type="button" class="button secondary" data-reveal="track-resident">Track Resident</button></div>
<form method="get" class="panel filters"><input type="hidden" name="page" value="residents"><div id="track-resident" <?= isset($_GET['search'])?'':'hidden' ?>><label>Name or email<input name="search" maxlength="255" value="<?= e($search) ?>" <?= isset($_GET['search'])?'':'disabled' ?>></label><button class="button primary">Search</button></div><label>Registrations<select name="status"><option value="">All Registrations</option><?php options(['Pending','Approved','Rejected'],$status); ?></select></label><button class="button secondary">Apply filter</button><a href="index.php?page=residents">Reset</a></form>
<?php if($invalid): ?><dialog data-auto-open><h2>Invalid</h2><a class="button primary" href="index.php?page=residents">OK</a></dialog><?php endif; ?>
<section class="panel table-scroll"><table><thead><tr><th>Resident</th><th>Email</th><th>Contact</th><th>Location</th><th>Registration</th><th>Action</th></tr></thead><tbody><?php foreach($residents as $resident): ?><tr><td><?= e($resident['first_name'].' '.$resident['last_name']) ?></td><td><?= e($resident['email']) ?></td><td><?= e($resident['contact_number']) ?></td><td><?= e($resident['sitio'].', '.$resident['barangay']) ?></td><td><span class="badge"><?= e($resident['status']==='Verified'?'Approved':$resident['status']) ?></span></td><td><a class="button secondary compact" href="index.php?page=residents&open=<?= (int)$resident['id'] ?>">View registration</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$residents): ?><p class="empty">No residents found.</p><?php endif; ?></section>
<?php $open=query_input('open'); $resident=ctype_digit($open)?(rows("SELECT * FROM users WHERE id=? AND role='resident'",[(int)$open])[0]??null):null; if($resident): ?>
<section class="panel dashboard-actions"><h2><?= e($resident['first_name'].' '.$resident['last_name']) ?></h2><p><?= e($resident['email']) ?> · <?= e($resident['status']==='Verified'?'Approved':$resident['status']) ?></p><div class="form-grid"><?php foreach(['front'=>'National ID — front','back'=>'National ID — back'] as $side=>$label): ?><figure><figcaption><?= e($label) ?></figcaption><a href="media.php?resident=<?= (int)$resident['id'] ?>&side=<?= e($side) ?>" target="_blank" rel="noopener"><img class="national-id" src="media.php?resident=<?= (int)$resident['id'] ?>&side=<?= e($side) ?>" alt="<?= e($label) ?>"></a></figure><?php endforeach; ?></div><?php if($resident['status']==='Pending'): ?><?php action_form('registration',(int)$resident['id']); ?><div class="button-row"><button class="button primary" name="status" value="Approved">Approve</button><button class="button danger" name="status" value="Rejected">Reject</button></div></form><?php endif; ?></section><?php endif; ?>
